/// <summary>
/// Concrete class for calculating MDF based on Picking Route
/// </summary>
public class METCustomerMDFCalculation_PickingRoute extends METCustomerMDFCalculation
{
    WMSPickingRouteID pickingRouteId;

}

Method.Source:
/// <summary>
/// Update query for processing
/// </summary>
/// <param name = "_query">Query</param>
/// <returns>Query</returns>
Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(WMSOrderTrans));
    qbds.addRange(fieldNum(WMSOrderTrans, RouteId)).value(pickingRouteId);

    return ret;
}

/// <summary>
/// Get or set the picking route id
/// </summary>
/// <param name = "_pickingRouteId">WMSPickingRouteID</param>
/// <returns>WMSPickingRouteID</returns>
public WMSPickingRouteID parmWMSPickingRouteID(WMSPickingRouteID _pickingRouteId = pickingRouteId)
{
    pickingRouteId = _pickingRouteId;

    return pickingRouteId;
}
